import MacbookPro from "./macbook-pro"

export default function Page() {
  return (
    <div className="px-4 py-10 md:px-6 md:py-14">
      <MacbookPro />
    </div>
  )
}

import { cn } from "@/lib/utils"

import MacbookScreen, {
  type MacbookScreenProps,
} from "./components/macbook-screen"

import "./styles/macbook-pro.css"

type MacbookProProps = {
  className?: string
} & Omit<MacbookScreenProps, "className">

export default function MacbookPro({
  className,
  minHeight,
  aspectRatio = "16 / 10",
  children,
}: MacbookProProps) {
  return (
    <div
      className={cn("mbp-root mbp-shell mx-auto w-full min-w-0 max-w-4xl", className)}
      role="img"
      aria-label="MacBook Pro device frame mockup"
    >
      <div className="mbp-lid">
        <div className="mbp-lid-frame">
          <div className="mbp-bezel">
            <div className="mbp-notch" aria-hidden>
              <span className="mbp-camera" />
            </div>
            <MacbookScreen
              minHeight={minHeight}
              aspectRatio={aspectRatio}
            >
              {children}
            </MacbookScreen>
          </div>
        </div>
      </div>

      <div className="mbp-hinge" aria-hidden />

      <div className="mbp-base" aria-hidden>
        <div className="mbp-scoop" />
      </div>
    </div>
  )
}

import type { CSSProperties, ReactNode } from "react"

import { cn } from "@/lib/utils"

export type MacbookScreenProps = {
  className?: string
  /** Minimum height when the screen is empty (default `20rem`) */
  minHeight?: string | number
  /** e.g. `"16 / 10"` — keeps the display opening proportional when set */
  aspectRatio?: string
  children?: ReactNode
}

export default function MacbookScreen({
  className,
  minHeight = "20rem",
  aspectRatio,
  children,
}: MacbookScreenProps) {
  const style = {
    ...(aspectRatio ? { aspectRatio } : {}),
    minHeight: typeof minHeight === "number" ? `${minHeight}px` : minHeight,
  } satisfies CSSProperties

  return (
    <div className={cn("mbp-screen", className)} style={style}>
      {children ? <div className="mbp-screen-slot">{children}</div> : null}
    </div>
  )
}

/* macbook-pro — Space Gray device frame; screen stays transparent by default */

.mbp-root {
  /* Space Gray — shared across lid, bezels, and base */
  --mbp-space-light: #3a3a3c;
  --mbp-space-mid: #2c2c2e;
  --mbp-space-dark: #1d1d1f;
  --mbp-space-deep: #141416;
  --mbp-frame-top: var(--mbp-space-light);
  --mbp-frame-mid: var(--mbp-space-mid);
  --mbp-frame-bottom: var(--mbp-space-dark);
  --mbp-frame-highlight: rgb(255 255 255 / 0.08);
  --mbp-frame-shadow: rgb(0 0 0 / 0.4);
  --mbp-bezel: var(--mbp-space-deep);
  --mbp-notch: var(--mbp-space-deep);
  --mbp-hinge: var(--mbp-space-dark);
  --mbp-base-top: var(--mbp-space-mid);
  --mbp-base-mid: var(--mbp-space-dark);
  --mbp-base-bottom: var(--mbp-space-deep);
  --mbp-scoop: var(--mbp-space-deep);
  --mbp-shell-shadow: 0 24px 48px -16px rgb(0 0 0 / 0.28);
  --mbp-shell-ring: rgb(0 0 0 / 0.2);
}

.dark .mbp-root {
  --mbp-shell-shadow: 0 28px 56px -16px rgb(0 0 0 / 0.55);
  --mbp-shell-ring: rgb(255 255 255 / 0.08);
}

.mbp-shell {
  display: flex;
  flex-direction: column;
  align-items: center;
  filter: drop-shadow(var(--mbp-shell-shadow));
}

/* Lid — display assembly */

.mbp-lid {
  position: relative;
  z-index: 1;
  width: 100%;
}

.mbp-lid-frame {
  border-radius: 0.75rem 0.75rem 0 0;
  padding: 0.375rem;
  background: linear-gradient(
    180deg,
    var(--mbp-frame-top) 0%,
    var(--mbp-frame-mid) 42%,
    var(--mbp-frame-bottom) 100%
  );
  box-shadow:
    inset 0 1px 0 var(--mbp-frame-highlight),
    inset 0 -1px 0 var(--mbp-frame-shadow),
    0 0 0 1px var(--mbp-shell-ring);
}

.mbp-bezel {
  position: relative;
  overflow: hidden;
  border-radius: 0.5rem 0.5rem 0 0;
  background: transparent;
}

.mbp-notch {
  position: absolute;
  top: 0;
  left: 50%;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  width: 13%;
  min-width: 4.5rem;
  max-width: 7.5rem;
  height: 1.25rem;
  padding-bottom: 0.2rem;
  border-radius: 0 0 0.5rem 0.5rem;
  background-color: var(--mbp-notch);
  transform: translateX(-50%);
}

.mbp-camera {
  position: relative;
  display: block;
  width: 0.4375rem;
  height: 0.4375rem;
  flex-shrink: 0;
  border-radius: 50%;
  background: radial-gradient(
    circle at 38% 32%,
    #4a4a58 0%,
    #252530 38%,
    #121218 72%,
    #08080c 100%
  );
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 0.85),
    0 0 0 1.5px rgb(55 55 62 / 0.9),
    inset 0 1px 2px rgb(0 0 0 / 0.55),
    inset 0 -0.5px 0 rgb(255 255 255 / 0.06);
}

.mbp-camera::before {
  content: "";
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  background: radial-gradient(
    circle at 40% 35%,
    #1e1e28 0%,
    #0c0c12 100%
  );
  box-shadow: inset 0 0 1px rgb(0 0 0 / 0.8);
}

.mbp-camera::after {
  content: "";
  position: absolute;
  top: 22%;
  left: 30%;
  width: 28%;
  height: 28%;
  border-radius: 50%;
  background: radial-gradient(
    circle at 50% 50%,
    rgb(255 255 255 / 0.5) 0%,
    rgb(255 255 255 / 0.12) 55%,
    transparent 100%
  );
}

/* Screen opening — transparent; bezels are borders so the hole shows the page behind */

.mbp-screen {
  position: relative;
  z-index: 1;
  width: 100%;
  overflow: hidden;
  border: 0.5rem solid var(--mbp-bezel);
  border-bottom-width: 1.125rem;
  border-radius: 0.25rem;
  background: transparent;
  box-sizing: border-box;
}

.mbp-screen-slot {
  position: absolute;
  inset: 0;
  display: flex;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.mbp-screen-slot > * {
  flex: 1;
  min-width: 0;
  min-height: 0;
}

/* Hinge */

.mbp-hinge {
  flex-shrink: 0;
  width: 100%;
  height: 2px;
  margin-block: -1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--mbp-hinge) 8%,
    var(--mbp-hinge) 92%,
    transparent 100%
  );
}

/* Base — wider chassis with thumb scoop */

.mbp-base {
  position: relative;
  z-index: 0;
  width: 104%;
  height: 2rem;
  border-radius: 0 0 0.875rem 0.875rem;
  background: linear-gradient(
    180deg,
    var(--mbp-base-top) 0%,
    var(--mbp-base-mid) 55%,
    var(--mbp-base-bottom) 100%
  );
  box-shadow:
    inset 0 1px 0 var(--mbp-frame-highlight),
    inset 0 -2px 4px var(--mbp-frame-shadow);
}

.mbp-scoop {
  position: absolute;
  top: 4px;
  left: calc(50% + 4px);
  z-index: 0;
  width: 28%;
  min-width: 5rem;
  max-width: 10rem;
  height: 0.5rem;
  border-radius: 0 0 0.5rem 0.5rem;
  background: var(--mbp-scoop);
  box-shadow: inset 0 -1px 2px rgb(0 0 0 / 0.45);
  transform: translate(-50%, -50%);
}
